style.css:
/* Midnight Emerald — Global */

/* i really want this to be global */

/* swap these values to change the theme */
:root {
  --my-bg: #080b09;
  --my-surface: #101713;
  --my-accent: #16c96b;
  --my-text: #edf5ef;
  --my-muted: #929e95;
  --my-border: rgba(255,255,255,0.09);
}

/* clean dark foundation */
body {
  background-color: var(--my-bg) !important;
  color: var(--my-text) !important;
  font-family: Inter, "Segoe UI", sans-serif !important;
}

/* cleaner text */
h1, h2, h3, h4 {
  letter-spacing: -0.035em !important;
  line-height: 1.2 !important;
}

/* emerald links */
a {
  color: var(--my-accent) !important;
  text-decoration: none !important;
}

/* smoother images */
img {
  border-radius: 10px;
}

/* cleaner buttons */
button {
  border-radius: 8px !important;
  transition: opacity 0.2s ease !important;
}

/* subtle separators */
hr {
  border-color: var(--my-border) !important;
}

/* calmer selection */
::selection {
  background: var(--my-accent) !important;
  color: #061009 !important;
}
